// Menjaga identitas komponen halaman tetap stabil lintas render, supaya perubahan state di App
// (mis. like, favorit, dsb) tidak bikin halaman aktif ke-remount ulang (yang akan mereset scroll).
function useStablePage(renderFn) {
  const fnRef = useRef(renderFn);
  fnRef.current = renderFn;
  const stableRef = useRef((props) => fnRef.current(props));
  return stableRef.current;
}

