  function NotificationsPage() {
    function markAllRead() {
      setNotifications((ns) => ns.map((n) => ({ ...n, read: true })));
    }
    function handleNotifClick(n) {
      setNotifications((ns) => ns.map((x) => (x.id === n.id ? { ...x, read: true } : x)));
      const t = n.target;
      if (!t) return;
      if (t.screen === "chat") {
        setActiveChatId(t.chatId);
        navigate("chatConversation");
      } else if (t.screen === "item") {
        const item = dibagi.find((d) => d.id === t.itemId);
        if (item) {
          setSelectedItem(item);
          setItemSource("dibagi");
          navigate("itemDetail");
        }
      } else if (t.screen === "profile") {
        navRoot("profile");
      }
    }
    return (
      <div className="h-full w-full flex flex-col" style={{ background: C.bg }}>
        <StatusBar />
        <Header
          title="Notifikasi"
          onBack={goBack}
          right={
            notifications.some((n) => !n.read) ? (
              <button onClick={markAllRead} className="fsz-11 font-bold" style={{ color: C.tosca }}>
                Tandai dibaca
              </button>
            ) : <div className="w-9 h-9" />
          }
        />
        <div className="flex-1 overflow-y-auto px-5 pb-8">
          {notifications.length === 0 ? (
            <div className="text-center py-20">
              <Bell size={36} color="#CBD5E1" className="mx-auto mb-3" />
              <p className="fsz-13 tc-gray font-medium">Belum ada notifikasi</p>
            </div>
          ) : (
            <div className="flex flex-col gap-2">
              {notifications.map((n) => {
                const Icon = NOTIF_ICON[n.type] || Info;
                return (
                  <button
                    key={n.id}
                    onClick={() => handleNotifClick(n)}
                    className="flex items-start gap-3 rounded-2xl p-3.5 text-left transition active:scale-95"
                    style={{ background: n.read ? "transparent" : "rgba(20,207,185,0.06)" }}
                  >
                    <div className="w-10 h-10 rounded-full flex items-center justify-center shrink-0" style={{ background: n.read ? C.gray : "rgba(20,207,185,0.15)" }}>
                      <Icon size={17} color={n.read ? "#94A3B8" : C.tosca} />
                    </div>
                    <div className="flex-1 min-w-0">
                      <p className="font-display font-bold fsz-13 leading-snug" style={{ color: C.text }}>{n.title}</p>
                      <p className="fsz-12 tc-slate font-medium mt-0.5 leading-snug">{n.body}</p>
                      <p className="fsz-10p5 tc-gray font-semibold mt-1.5">{n.time}</p>
                    </div>
                    {!n.read && <span className="w-2 h-2 rounded-full shrink-0 mt-1.5" style={{ background: C.tosca }} />}
                  </button>
                );
              })}
            </div>
          )}
        </div>
      </div>
    );
  }

