  function SavedLocationsPage() {
    const [showPicker, setShowPicker] = useState(false);

    function addLocation(address) {
      setSavedLocations((ls) => [...ls, { id: "l" + Date.now(), label: "Lokasi Baru", address }]);
      setShowPicker(false);
    }
    function removeLocation(id) {
      setSavedLocations((ls) => ls.filter((l) => l.id !== id));
    }
    function useLocation(address) {
      setUserLokasi(address);
      showToast("Lokasi utama diperbarui");
    }

    return (
      <div className="h-full w-full flex flex-col relative" style={{ background: C.bg }}>
        <StatusBar />
        <Header title="Lokasi Tersimpan" onBack={goBack} />
        <div className="flex-1 overflow-y-auto px-5 pb-8">
          <div className="flex flex-col gap-3">
            {savedLocations.map((loc) => {
              const isActive = loc.address === userLokasi;
              return (
                <div key={loc.id} className="rounded-2xl p-4" style={{ background: isActive ? "rgba(20,207,185,0.08)" : C.gray }}>
                  <div className="flex items-start gap-3">
                    <div className="w-9 h-9 rounded-full flex items-center justify-center shrink-0" style={{ background: isActive ? "rgba(20,207,185,0.15)" : "#fff" }}>
                      <MapPin size={16} color={isActive ? C.tosca : "#94A3B8"} />
                    </div>
                    <div className="flex-1 min-w-0">
                      <div className="flex items-center gap-2">
                        <p className="font-display font-bold fsz-13p5" style={{ color: C.text }}>{loc.label}</p>
                        {isActive && (
                          <span className="px-2 py-0.5 rounded-full fsz-10p5 font-bold" style={{ background: C.tosca, color: "#fff" }}>Aktif</span>
                        )}
                      </div>
                      <p className="fsz-12 tc-slate font-medium mt-0.5">{loc.address}</p>
                      <div className="flex items-center gap-4 mt-2.5">
                        {!isActive && (
                          <button onClick={() => useLocation(loc.address)} className="fsz-11p5 font-bold" style={{ color: C.tosca }}>Gunakan</button>
                        )}
                        {savedLocations.length > 1 && (
                          <button onClick={() => removeLocation(loc.id)} className="fsz-11p5 font-bold" style={{ color: "#EF4444" }}>Hapus</button>
                        )}
                      </div>
                    </div>
                  </div>
                </div>
              );
            })}
          </div>
        </div>
        <div className="px-5 pb-6 pt-2 shrink-0">
          <PrimaryButton onClick={() => setShowPicker(true)} icon={Plus}>Tambah Lokasi</PrimaryButton>
        </div>
        {showPicker && (
          <LocationPickerSheet
            value={userLokasi}
            onSelect={addLocation}
            onClose={() => setShowPicker(false)}
            title="Tambah Lokasi Tersimpan"
          />
        )}
      </div>
    );
  }

